import javax.ws.rs.ext.RuntimeDelegate;
import java.util.regex.Pattern;

/**
 * A delegate for parsing and formatting {@code MediaType} values.
 * <p>
 * The {@link #isValid(String)} method has been rewritten to use a strict
 * whitelist based on RFC 7230 token rules. It now accepts only characters
 * that are guaranteed to be safe in HTTP header field values, thereby
 * preventing header injection via unescaped control characters such as
 * {@code \r} or {@code \n}. The wildcard character {@code "*"} is still
 * permitted as a special case.
 */
public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    // RFC 7230 tchar definition: !#$%&'*+-.^_`|~ plus alphanumerics
    private static final Pattern TOKEN_PATTERN =
            Pattern.compile("^[A-Za-z0-9!#$%&'*+\\-.^_`|~]+$");

    /**
     * Validates a media type component (major or subtype).
     *
     * @param str the component to validate
     * @return {@code true} if the component is non‑null, non‑empty, and
     *         contains only allowed characters; {@code false} otherwise
     */
    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }

        // Allow the wildcard "*" as a special case
        if ("*".equals(str)) {
            return true;
        }

        // Reject any control characters or whitespace explicitly
        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);
            if (Character.isISOControl(ch) || Character.isWhitespace(ch)) {
                return false;
            }
        }

        // Ensure the string matches the RFC 7230 token pattern
        return TOKEN_PATTERN.matcher(str).matches();
    }

    // other methods
}
