            throw new IOException("Unexpected end of stream");
        }
        if (n == 0) {
            throw new IOException("Invalid RLE packet length 0");
        }
        if (n > 128) {
            int value = in.read();
            if (value == -1) {
                throw new IOException("Unexpected end of stream while reading repeat value");
            }
            int count = n & 0x7F;
            if (position + count > total) {
                throw new IOException("RLE packet exceeds output buffer size");
            }
            for (int i = 0; i < count; i++) {
