class RgbeInfo implements Closeable {

    private final InputStream in;

    // other methods

    /**
     * Decompresses data from the given {@link InputStream} into the supplied
     * output buffer using a simple RLE scheme. The method performs strict
     * validation of the input stream to guard against malformed data and
     * potential denial‑of‑service attacks caused by infinite loops or
     * excessive memory usage.
     *
     * @param in  the source stream containing compressed data
     * @param out the buffer to receive decompressed bytes
     * @throws IOException if the stream ends unexpectedly or contains
     *                     invalid packet lengths
     */
    private static void decompress(final InputStream in, final byte[] out) throws IOException {
        int position = 0;
        final int total = out.length;

        while (position < total) {
            int n = in.read();
            if (n == -1) {
                throw new EOFException("Unexpected end of stream while reading packet header");
            }

            // A packet length of 0 is not valid in the Rgbe format
            if (n == 0) {
                throw new IOException("Invalid packet length 0 encountered during decompression");
            }

            if (n > 128) { // Run‑length encoded packet
                int value = in.read();
                if (value == -1) {
                    throw new EOFException("Unexpected end of stream while reading repeat value");
                }
                int count = n & 0x7F; // Number of repetitions

                if (position + count > total) {
                    throw new IOException("Run‑length packet exceeds output buffer size");
                }

                for (int i = 0; i < count; i++) {
                    out[position++] = (byte) value;
                }
            } else { // Literal packet
                int count = n;

                if (position + count > total) {
                    throw new IOException("Literal packet exceeds output buffer size");
                }

                for (int i = 0; i < count; i++) {
                    int b = in.read();
                    if (b == -1) {
                        throw new EOFException("Unexpected end of stream while reading literal data");
