import com.opensymphony.xwork2.util.LocalizedTextUtil;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import java.util.Locale;
import java.util.regex.Pattern;

public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    /* --------------------------------------------------------------------- */
    /*  Locale validation utilities                                           */
    /* --------------------------------------------------------------------- */

    /**
     * Regular expression that matches valid ISO‑639 language codes
     * optionally followed by a country code and an optional variant.
     * Examples of accepted values: "en", "en_US", "en-US", "fr_CA_POSIX".
     */
    private static final Pattern VALID_LOCALE_PATTERN =
            Pattern.compile("^[a-zA-Z]{2,3}([_-][a-zA-Z]{2})?([_-][\\w\\d]{1,8})?$");

    /**
     * Checks whether the supplied string conforms to the expected locale format.
     *
     * @param localeStr the locale string to validate
     * @return true if the string matches the pattern, false otherwise
     */
    private static boolean isValidLocaleString(String localeStr) {
        return localeStr != null && !localeStr.isEmpty() &&
               VALID_LOCALE_PATTERN.matcher(localeStr).matches();
    }

    /* --------------------------------------------------------------------- */
    /*  Core interceptor logic                                                */
    /* --------------------------------------------------------------------- */

    /**
     * Creates a {@link Locale} object from the request param, which might
     * already be a {@code Locale} or a {@code String}.  The method validates
     * the string representation against a strict whitelist to prevent
     * injection of malicious content.
     *
     * @param requestedLocale the parameter from the request
     * @return the {@link Locale} or {@code null} if the input is invalid
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        if (requestedLocale == null) {
            return null;
        }

        Locale locale = null;

        if (requestedLocale instanceof Locale) {
            locale = (Locale) requestedLocale;
        } else {
            String localeStr = requestedLocale.toString().trim();

            if (isValidLocaleString(localeStr)) {
                try {
                    locale = LocalizedTextUtil.localeFromString(localeStr, null);
                } catch (IllegalArgumentException e) {
                    // Defensive: log and ignore malformed locale strings
                    LOG.warn("Failed to parse locale string '{}': {}", localeStr, e.getMessage());
                }
            } else {
                LOG.warn("Received invalid locale string: '{}'", localeStr);
            }
        }

        if (locale != null) {
            LOG.debug("Applied request locale: {}", locale);
        }

        return locale;
    }

    // other methods
}
