            Path entryPathObj = Paths.get(entryName);
            if (entryPathObj.isAbsolute()) {
                throw new IOException("absolute entry name not allowed: " + entryName);
            }

            // Resolve the entry against the target directory and normalise to eliminate '..' components
            Path resolvedPath = targetDirPath.resolve(entryPathObj).normalize();

            // Ensure the resolved path is still within the target directory
            if (!resolvedPath.startsWith(targetDirPath)) {
                throw new IOException("expanding " + entryName + " would create file outside of " + targetDirectory);
