private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Handle entries that use a data descriptor – the data is already cached.
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry(); // populate lastStoredEntry
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    final long csize = current.entry.getSize();

    // If the size is unknown (negative), fall back to reading until the underlying
    // stream signals EOF. This protects against malformed archives that omit the
    // size field.
    if (csize < 0) {
        // Read directly from the underlying stream into the caller's buffer.
        int read = in.read(buffer, offset, length);
        if (read > 0) {
            count(read);
            current.bytesReadFromStream += read;
        }
        return read;
    }

    // If the entry has zero length, signal EOF immediately.
    if (csize == 0) {
        return -1;
    }

    // Guard against corrupt archives where the reported size is smaller than
    // the amount of data already consumed. This prevents an infinite loop
    // caused by a malicious or damaged ZIP file.
    if (current.bytesReadFromStream > csize) {
        throw new IOException("ZIP entry size mismatch: read more data than declared");
    }

    // If we've already read the declared number of bytes, signal EOF.
    if (current.bytesRead >= csize) {
        return -1;
