    public String getValidHref(final String url) {
        if (StringUtils.isBlank(url)) {
            return "";
        }

        try {
            // Trim whitespace to avoid accidental leading/trailing spaces
            String trimmed = url.trim();

            // Reject URLs containing control characters that could be used for injection
            if (trimmed.matches(".*[\\p{Cntrl}].*")) {
                return "";
            }

            // Parse the URL using java.net.URI – this will reject malformed URLs
            URI uri = new URI(trimmed);

            // If a scheme is present, ensure it is one of the allowed safe schemes
            String scheme = uri.getScheme();
            if (scheme != null && !isAllowedScheme(scheme)) {
                return "";
            }

            // Convert to ASCII form – this percent‑encodes non‑ASCII characters
            String encoded = uri.toASCIIString();

            // Escape characters that are problematic in HTML attributes
            encoded = encoded.replace("\"", "%22")
                             .replace("'", "%27")
                             .replace("<", "%3C")
                             .replace(">", "%3E")
                             .replace("`", "%60");

            // Preserve any namespace mangling required by the application
            encoded = mangleNamespaces(encoded);

            // Final validation using the XSSFilter
            if (xssFilter.isValidHref(encoded)) {
                return encoded;
            }
        } catch (URISyntaxException e) {
            LOGGER.warn("Invalid URL syntax: {}", url);
        }

        return "";
    }

